// Sourcing reads an Apollo saved-search CSV export, not the Apollo API: the Free
// plan blocks every prospecting endpoint even with a master key (checked
// 2026-09-08). Apollo writes a different header set per column preset, so the
// column mapping lives in `apollo_column_map` on Load Run Config and this node
// only resolves it. Nothing about the column set is hardcoded here.
const cfg = $('Load Run Config').first().json;

let map = cfg.apollo_column_map;
if (typeof map === 'string') { map = JSON.parse(map); }
if (!map || typeof map !== 'object') {
  throw new Error('Normalize Prospect List: apollo_column_map is missing or unparseable on Load Run Config');
}

const limit = Number(cfg.prospect_row_limit) || 20;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
if (rows.length === 0) {
  throw new Error('Normalize Prospect List: the export parsed to zero rows. Check prospect_csv_path and that the file has a header row.');
}

// Header matching ignores case, spaces, punctuation and a leading BOM, so
// "# Employees", "#employees" and "Employees" all resolve to the same field.
const norm = s => String(s == null ? '' : s).replace(/^\uFEFF/, '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const headers = Object.keys(rows[0]);
const byNorm = {};
for (const h of headers) { byNorm[norm(h)] = h; }

const resolved = {};
const unresolved = [];
for (const [field, aliases] of Object.entries(map)) {
  const list = Array.isArray(aliases) ? aliases : [aliases];
  const hit = list.map(norm).find(a => byNorm[a]);
  if (hit) { resolved[field] = byNorm[hit]; } else { unresolved.push(field); }
}

// Fail loud, not quiet. The company name is what the QA gate checks the draft
// for (rule 3), so an unresolved company column would let generic mail pass the
// gate on a technicality.
if (!resolved.company) {
  throw new Error('Normalize Prospect List: no company column resolved. Add the real header to apollo_column_map.company. Headers found: ' + headers.join(' | '));
}
// With no firmographic column there is nothing to draft from but the name, and
// the email would be the same for every prospect.
const research = ['title', 'industry', 'employee_count', 'company_domain'].filter(f => resolved[f]);
if (research.length === 0) {
  throw new Error('Normalize Prospect List: no research column resolved (title, industry, employee count or domain). Headers found: ' + headers.join(' | '));
}

const val = (row, field) => {
  if (!resolved[field]) return '';
  const raw = row[resolved[field]];
  return String(raw == null ? '' : raw).trim();
};

// Real addresses stop here. The destination is overridden before the send
// anyway (Force Lab Recipient), so the flow keeps a masked form as proof the
// row carried an address and drops the deliverable one. Nothing downstream,
// including the outbox table and any screenshot of a run, sees a real inbox.
const maskEmail = e => {
  const at = e.indexOf('@');
  if (at < 1) return '';
  return e.slice(0, 1) + '***@' + e.slice(at + 1);
};

const out = [];
rows.slice(0, limit).forEach((row, idx) => {
  const company = val(row, 'company');
  if (!company) return;
  const first = val(row, 'first_name');
  const last = val(row, 'last_name');
  const employees = val(row, 'employee_count');
  const notes = [
    val(row, 'industry'),
    employees ? employees + ' employees' : '',
    [val(row, 'city'), val(row, 'state'), val(row, 'country')].filter(Boolean).join(', '),
    val(row, 'company_domain'),
    val(row, 'description'),
  ].filter(Boolean).join(' | ');

  out.push({ json: {
    run_id: cfg.run_id,
    prospect_id: val(row, 'prospect_id') || ('csv-' + (idx + 1)),
    company: company,
    contact: [first, last].filter(Boolean).join(' ') || 'there',
    contact_title: val(row, 'title'),
    prospect_email: maskEmail(val(row, 'email')),
    prospect_email_masked: true,
    website: val(row, 'company_domain'),
    industry: val(row, 'industry'),
    employee_count: employees ? (Number(String(employees).replace(/[^0-9]/g, '')) || null) : null,
    research_notes: notes,
    source: 'apollo_shaped_csv',
    csv_columns_resolved: Object.keys(resolved).join(','),
    csv_columns_unresolved: unresolved.join(','),
    qa_attempts: 0,
    qa_reason: '',
    row_index: idx,
  } });
});

if (out.length === 0) {
  throw new Error('Normalize Prospect List: every parsed row was missing a company name');
}
return out;

// Takes a plain { company, contact } item. Nothing here reads batch state, so a
// single-company call can feed this node directly.
const item = $json;
const company = String(item.company || item.company_name || '').trim();
const contact = String(item.contact || item.first_name || 'there').trim();
const title = String(item.contact_title || item.title || '').trim();
const research = String(
  item.research_notes ||
  [item.industry, item.employee_count ? item.employee_count + ' employees' : '', item.website]
    .filter(Boolean).join(' | ')
).trim();

if (!company) {
  throw new Error('Build Personalization Prompt needs a company name on the input item');
}

const qaAttempts = Number(item.qa_attempts || 0);
const qaReason = String(item.qa_reason || '');

const rules = [
  'Write one cold outbound opening email.',
  'The body must be between 25 and 60 words. Count the words before answering.',
  'The body must name the company exactly as "' + company + '".',
  'Never write "I hope this email finds you", "I hope you are doing well", "Dear Sir/Madam" or "To whom it may concern".',
  'Leave no template token unfilled. No {{ }}, no [Company], no [Name].',
  'Never copy more than 15 words in a row from the research notes.',
  'Plain sentences, no em dash, no exclamation marks.',
  'Answer with JSON only: {"subject": "...", "body": "..."}',
];

// drill_mode on Load Run Config: 'off' for real runs. 'reject_all' or
// 'reject_alternate' (odd rows only) swap in rules that break the gate on purpose,
// so the drill shows the gate refusing real model output.
const drill = String($('Load Run Config').first().json.drill_mode || 'off');
const forceBad = drill === 'reject_all' || (drill === 'reject_alternate' && Number(item.row_index) % 2 === 1);
if (forceBad) {
  rules.length = 0;
  rules.push(
    'Write one cold outbound opening email.',
    'Start the body with exactly: I hope this email finds you well.',
    'Do not mention the company by name anywhere.',
    'Keep the body under 20 words.',
    'Answer with JSON only: {"subject": "...", "body": "..."}',
  );
}

let user = 'Prospect'
  + '\nContact: ' + contact + (title ? ' (' + title + ')' : '')
  + '\nCompany: ' + company
  + (research ? '\nResearch notes: ' + research : '')
  + '\n\nRules\n' + rules.map((r, i) => (i + 1) + '. ' + r).join('\n');

if (qaReason) {
  user += '\n\nThe previous draft was rejected by the QA gate. Reason: ' + qaReason
    + '\nFix exactly that and keep every rule above. This is redraft attempt '
    + qaAttempts + '.';
}

return { json: Object.assign({}, item, {
  company: company,
  contact: contact,
  contact_title: title,
  research_notes: research,
  qa_attempts: qaAttempts,
  qa_reason: qaReason,
  drill_forced_bad: forceBad,
  system_prompt: 'You write short cold outbound emails for B2B sales. You answer with JSON only.',
  user_prompt: user,
}) };

// Real exponential backoff with jitter: wait = 500ms * 2^attempt + jitter,
// capped at 30s, and a Retry-After header wins over the computed value.
const attempt = $runIndex;
const errRaw = $json.error !== undefined ? $json.error : $json;
// n8n hands the error back as a string on some node types and as an object on others.
const errObj = (typeof errRaw === 'string') ? { message: errRaw } : (errRaw || {});
const statusCode = errObj.statusCode || errObj.status || errObj.httpCode
  || (errObj.cause && errObj.cause.statusCode) || null;
const headers = errObj.headers || (errObj.response && errObj.response.headers) || {};
const retryAfterHeader = headers['retry-after'] || headers['Retry-After'];

const maxAttempts = 3;
const retryableCodes = [408, 409, 425, 429, 500, 502, 503, 504];
const isRetryable = statusCode === null || retryableCodes.indexOf(Number(statusCode)) !== -1;
const shouldRetry = isRetryable && attempt < maxAttempts;

let delayMs;
if (retryAfterHeader) {
  delayMs = Number(retryAfterHeader) * 1000;
} else {
  const base = 500 * Math.pow(2, attempt);
  const jitter = Math.floor(Math.random() * 250);
  delayMs = Math.min(30000, base + jitter);
}

return { json: {
  attempt: attempt,
  statusCode: statusCode,
  shouldRetry: shouldRetry,
  delaySeconds: Math.max(Math.ceil(delayMs / 1000), 1),
  reason: String(errObj.message || errObj.description || 'openai call failed').slice(0, 400),
} };

// Backoff exhausted. Do not drop the prospect: hand it to the needs_review path
// with the failure recorded, same as a draft the QA gate could not clear.
//
// The lookback is deliberately defensive. An error output does not always carry
// paired-item metadata back to the node that produced the input, and this node
// exists precisely so a failed draft call cannot lose a prospect. It must never
// be the thing that throws.
let src = {};
try {
  src = $('Build Personalization Prompt').item.json;
} catch (e) {
  const all = $('Build Personalization Prompt').all();
  const picked = all[$itemIndex] || all[0];
  src = (picked && picked.json) || {};
}

return { json: Object.assign({}, src, {
  qa_pass: false,
  qa_reason: 'draft_call_failed_after_backoff: ' + String($json.reason || ''),
  qa_attempts: Number(src.qa_attempts || 0),
  draft_subject: '',
  draft_body: '',
}) };

const src = $('Build Personalization Prompt').item.json;
const resp = $('Draft Email (OpenAI)').item.json;
const choice = (resp.choices || [])[0] || {};
const raw = String((choice.message && choice.message.content) || '');

let subject = '';
let body = '';
try {
  const parsed = JSON.parse(raw);
  subject = String(parsed.subject || '').trim();
  body = String(parsed.body || '').trim();
} catch (e) {
  // The model ignored the JSON contract. Fall back to first line = subject.
  const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);
  subject = (lines.shift() || '').replace(/^subject\s*:\s*/i, '').trim();
  body = lines.join(' ').trim();
}

return { json: Object.assign({}, src, {
  draft_subject: subject,
  draft_body: body,
  draft_raw: raw,
  finish_reason: choice.finish_reason || '',
}) };

// Four deterministic rules. Any one of them rejects the draft. No model judges
// the model here -- every check is something you can re-run by hand.
const item = $json;
const subject = String(item.draft_subject || '');
const body = String(item.draft_body || '');
const company = String(item.company || '');
const research = String(item.research_notes || '');
const attempts = Number(item.qa_attempts || 0);
const reasons = [];

// Rule 1 -- body word count must sit between 25 and 60.
const words = body.split(/\s+/).filter(Boolean);
if (words.length < 25 || words.length > 60) {
  reasons.push('rule_1_word_count: body has ' + words.length + ' words, allowed range is 25 to 60');
}

// Rule 2 -- no denylisted generic phrase, no unfilled template token.
const denylist = [
  'i hope this email finds you',
  'dear sir/madam',
  'to whom it may concern',
  "i hope you're doing well",
  'i hope you are doing well',
  'dear [first name]',
];
const haystack = (subject + ' ' + body).toLowerCase();
const phraseHit = denylist.find(p => haystack.indexOf(p) !== -1);
if (phraseHit) {
  reasons.push('rule_2_generic_phrase: contains "' + phraseHit + '"');
}
const tokenHit = (subject + ' ' + body).match(/\{\{|\[Company\]|\[Name\]|\[First Name\]/i);
if (tokenHit) {
  reasons.push('rule_2_unfilled_token: contains "' + tokenHit[0] + '"');
}

// Rule 3 -- the company name has to appear in the body.
if (!company || body.toLowerCase().indexOf(company.toLowerCase()) === -1) {
  reasons.push('rule_3_company_missing: the body never names "' + company + '"');
}

// Rule 4 -- no run of more than 15 words copied verbatim from the research text.
if (research) {
  const norm = s => s.toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const src = norm(research).split(' ').filter(Boolean);
  const dst = norm(body).split(' ').filter(Boolean);
  const N = 16; // "more than 15 words in a row"
  if (src.length >= N && dst.length >= N) {
    const seen = new Set();
    for (let i = 0; i + N <= src.length; i++) { seen.add(src.slice(i, i + N).join(' ')); }
    for (let i = 0; i + N <= dst.length; i++) {
      if (seen.has(dst.slice(i, i + N).join(' '))) {
        reasons.push('rule_4_verbatim_copy: 16 or more words copied straight from the research notes');
        break;
      }
    }
  }
}

const qaPass = reasons.length === 0;
return { json: Object.assign({}, item, {
  qa_pass: qaPass,
  qa_reason: qaPass ? '' : reasons.join('; '),
  qa_attempts: attempts,
  qa_word_count: words.length,
}) };

// One redraft costs one more OpenAI call, so the cap is what keeps a bad
// prospect from looping the run (and the spend) forever.
const cfg = $('Load Run Config').first().json;
const max = Number(cfg.max_redraft_attempts || 2);
const item = $json;
const attempts = Number(item.qa_attempts || 0) + 1;

return { json: Object.assign({}, item, {
  qa_attempts: attempts,
  redraft_exhausted: attempts > max,
  qa_reason: String(item.qa_reason || 'draft rejected by the QA gate'),
}) };

// Recipient safety. The prospect list carries prospect addresses; this is a lab,
// so the destination is overridden to a controlled address before the send node
// runs. The prospect fields stay only in the draft text and the outbox row.
const cfg = $('Load Run Config').first().json;
const src = $('QA Gate').item.json;
const outboxId = $json.id;

const lab = String(cfg.lab_recipient_email || '').trim();
const allow = String(cfg.lab_recipient_allowlist || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

if (!lab) {
  throw new Error('Force Lab Recipient: lab_recipient_email is empty in Load Run Config. Refusing to send.');
}
if (lab.indexOf('SET_ME') === 0) {
  throw new Error('Force Lab Recipient: lab_recipient_email is still the placeholder. Refusing to send.');
}
if (allow.length && allow.indexOf(lab.toLowerCase()) === -1) {
  throw new Error('Force Lab Recipient: lab_recipient_email is not on lab_recipient_allowlist. Refusing to send.');
}

// drill_mode 'sender_failure' hands the sender an address with no domain, so the
// send fails at Gmail and the error path runs. No third party is ever addressed.
const deliverTo = String(cfg.drill_mode || 'off') === 'sender_failure' ? 'sender-failure-drill' : lab;

return { json: {
  run_id: cfg.run_id,
  outbox_id: outboxId,
  send_to: lab,
  deliver_to: deliverTo,
  prospect_email_suppressed: true,
  company: src.company,
  contact: src.contact,
  contact_title: src.contact_title,
  draft_subject: src.draft_subject,
  draft_body: src.draft_body,
} };
